<?php
namespace Ishep\Http\Controllers;use Throwable;use DomainException;use Ishep\Bootstrap\Application as App;use Ishep\Http\{Request,Response};use Ishep\Validation\DocumentUploadValidator;
final class MemberDocumentController
{private function app():App{return App::instance();}private function uid():int{return(int)$this->app()->session()->get('user_id');}private function data():array{$a=$this->app()->applications()->latestForUser($this->uid());$docs=$a?$this->app()->documents()->currentForApplication((int)$a['id']):[];return['application'=>$a,'documents'=>$docs,'types'=>$a?$this->app()->documents()->types((int)$a['membership_type_id']):[],'counts'=>$this->app()->documents()->counts($this->uid()),'documentConfig'=>$this->app()->config('documents'),'documentStatuses'=>$this->app()->documentStatuses()];}public function index():Response{return$this->app()->render('membership/documents',$this->data());}private function fail(Throwable $e):Response{$message=$e instanceof DomainException?$e->getMessage():'The document request could not be completed safely.';if(!$e instanceof DomainException)$this->app()->logger()->log('error','Member document request failed',['exception'=>get_class($e),'user_id'=>$this->uid()]);$this->app()->session()->flash('errors',['document'=>[$message]]);return Response::redirect(url('/membership/application/documents'));}private function validated(Request $r):array{return(new DocumentUploadValidator($this->app()->config('documents')))->validate($r->files['document']??[]);}public function upload(Request $r):Response{try{$type=ctype_digit((string)($r->input['document_type_id']??''))?(int)$r->input['document_type_id']:0;$this->app()->documentService()->upload($this->uid(),$type,$this->validated($r),$r->ip());$this->app()->session()->flash('status','Document uploaded for verification.');return Response::redirect(url('/membership/application/documents'));}catch(Throwable $e){return$this->fail($e);}}public function replace(Request $r):Response{try{$this->app()->documentService()->replace($this->uid(),(string)$r->get('reference'),$this->validated($r),$r->ip());$this->app()->session()->flash('status','Replacement uploaded for verification.');return Response::redirect(url('/membership/application/documents'));}catch(Throwable $e){return$this->fail($e);}}public function remove(Request $r):Response{try{$this->app()->documentService()->remove($this->uid(),(string)$r->get('reference'),$r->ip());$this->app()->session()->flash('status','Document removed from the active checklist.');return Response::redirect(url('/membership/application/documents'));}catch(Throwable $e){return$this->fail($e);}}public function download(Request $r):Response{$d=$this->app()->documents()->byReference((string)$r->get('reference'));if(!$d||(int)$d['user_id']!==$this->uid()||in_array($d['verification_status'],['removed','replaced'],true))return$this->app()->render('errors/404',[],404);return$this->file($d);}public function file(array $d):Response{try{$path=$this->app()->documentStorage()->path($d['relative_path']);$name=str_replace(['"',"\r","\n"],'_',basename($d['original_filename']));return new Response((string)file_get_contents($path),200,['Content-Type'=>$d['detected_mime'],'Content-Disposition'=>'attachment; filename="'.$name.'"','Content-Length'=>(string)filesize($path),'X-Content-Type-Options'=>'nosniff','Cache-Control'=>'private, no-store, max-age=0']);}catch(Throwable){return$this->app()->render('errors/404',[],404);}}}
